package storage

import (
	"bytes"
	"crypto/sha256"
	"os"
	"reflect"
	"strings"
	"testing"
)

// The schema3 vector was independently assembled with Python shortest varints,
// length-prefixed fields and hashlib.sha256. It is not generated by this codec.
func TestCompactionManifestIndependentGolden(t *testing.T) {
	id, _, old, _ := metadataFixtures(t)
	genesis, err := GenesisPosition(id)
	if err != nil {
		t.Fatal(err)
	}
	source := LayoutSource{ManifestID: old.ManifestID, ManifestDigest: metadataDigest(t, "c59448666f8d63120b42e545f3f64fff5018a38a3eec399ff390f45344318254"), Generation: old.Generation, PublishedEnd: old.PublishedEnd, Position: old.Position, PostRootSet: old.PostRootSet}
	m := old
	m.Generation++
	m.ManifestID = "303132333435363738393a3b3c3d3e3f"
	m.SegmentID = "404142434445464748494a4b4c4d4e4f"
	m.SegmentHeaderDigest = metadataDigest(t, strings.Repeat("22", 32))
	m.PrefixDigest = metadataDigest(t, strings.Repeat("33", 32))
	m.LayoutSource = &source
	m.RetiredSegments = manifestDescriptors(old, genesis)
	raw, err := os.ReadFile("../testdata/compaction-manifest-schema3.hex")
	if err != nil {
		t.Fatal(err)
	}
	want := metadataHex(t, strings.TrimSpace(string(raw)))
	got, err := EncodeManifest(m)
	if err != nil || !bytes.Equal(got, want) {
		t.Fatalf("schema3 bytes differ: %x %v", got, err)
	}
	if len(got) != 544 || Digest(sha256.Sum256(got)).String() != "1322f4b5cb1c00cfa971202f84a959603de776672745e3a414b3a36f6431123b" {
		t.Fatal("independent checksum changed")
	}
	decoded, err := DecodeManifest(want)
	if err != nil || !reflect.DeepEqual(decoded, m) {
		t.Fatalf("schema3 decode: %+v %v", decoded, err)
	}
	for i := range want {
		if _, err = DecodeManifest(want[:i]); err == nil {
			t.Fatalf("truncation accepted at %d", i)
		}
		changed := bytes.Clone(want)
		changed[i] ^= 1
		if _, err = DecodeManifest(changed); err == nil {
			t.Fatalf("flipped byte accepted at %d", i)
		}
	}
	bad := m
	bad.RetiredSegments = append([]SegmentDescriptor(nil), m.RetiredSegments...)
	bad.RetiredSegments[0].SegmentID = m.SegmentID
	if _, err = EncodeManifest(bad); err == nil {
		t.Fatal("current segment authorized for retirement")
	}
	bad = m
	bad.LayoutSource = &LayoutSource{}
	*bad.LayoutSource = source
	bad.LayoutSource.Generation = m.Generation
	if _, err = EncodeManifest(bad); err == nil {
		t.Fatal("source generation CAS absent")
	}
}
